WITH scored AS (SELECT *, RANK() OVER (ORDER BY budget DESC NULLS FIRST) budget_rank, AVG(budget) OVER (ORDER BY budget, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) budget_avg_3, SUM(budget) OVER w_grp cumulative_budget, NTILE(10) OVER (PARTITION BY location ORDER BY budget, id) budget_bucket FROM departments WINDOW w_grp AS (PARTITION BY dept_name, location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, location, budget_rank, budget_avg_3, budget_bucket FROM scored;
